from pysat.solvers import Glucose3

# Number of vertices
n = 12

# Map edge (i, j) to index
edges = []
for i in range(n):
    for j in range(i + 1, n):
        edges.append((i, j))

edge_to_idx = {e: k for k, e in enumerate(edges)}

solver = Glucose3()

# Add clauses for each 4-clique
import itertools
for clique in itertools.combinations(range(n), 4):
    clique_edges = []
    for i, j in itertools.combinations(clique, 2):
        clique_edges.append(edge_to_idx[(i, j)])

    # Not all red (0) -> at least one is blue (1) -> at least one variable is True
    solver.add_clause([e + 1 for e in clique_edges])

    # Not all blue (1) -> at least one is red (0) -> at least one variable is False
    solver.add_clause([-(e + 1) for e in clique_edges])

# Add partial assignment
partial = {7: 0, 9: 0, 23: 1, 27: 0, 28: 0, 29: 0, 33: 1, 34: 0, 39: 1, 40: 0, 53: 0, 58: 0, 63: 0}
for k, v in partial.items():
    if v == 1:
        solver.add_clause([k + 1])
    else:
        solver.add_clause([-(k + 1)])

if solver.solve():
    model = solver.get_model()
    solution = [1 if x > 0 else 0 for x in model[:66]]
    print("SAT")
    print(solution)
else:
    print("UNSAT")
